"""
    given a list, return a list enumerated with prefix.
    """
def enumerate_with_prefix(a_list: Any, prefix: Any = 'pre_') -> object {
    num_digits = len(str(len(a_list)));
    enum_list = [
        (prefix + str(idx).zfill(num_digits)) for (idx, el) in enumerate(a_list)
    ];
    return enum_list;
}

